// Lesson 36: loads the site over HTTP and sends the dispatch report.
// The lesson 35 functions are unchanged; only start() and the HTTP section are new.
(function (root) {
  'use strict';

  const ISSUE_TYPES = {
    badge: 'No badge available',
    locked: 'Plant room locked',
    contact: 'Site contact unreachable'
  };
  const MAX_DETAILS = 2000;

  // HTTP settings. base '' = same origin as the page (the mock server serves both).
  const API = { base: '', timeoutMs: 10000, maxAttempts: 3 };

  function toBriefing(record) {
    if (record === null || typeof record !== 'object') {
      throw new TypeError('Site record must be an object');
    }
    const contacts = Array.isArray(record.cedar_site_contact) ? record.cedar_site_contact : [];
    const firstContact = contacts[0] ?? {};
    const formatted = record['cedar_afterhoursaccess@OData.Community.Display.V1.FormattedValue'];
    return {
      siteCode: String(record.cedar_sitecode ?? ''),
      siteName: String(record.cedar_name ?? ''),
      contact: firstContact.fullname
        ? firstContact.fullname + (firstContact.jobtitle ? ' (' + firstContact.jobtitle.toLowerCase() + ')' : '')
        : 'No site contact recorded',
      afterHours: formatted ?? (record.cedar_afterhoursaccess === true ? 'Yes' : 'No'),
      accessNotes: record.cedar_accessnotes ?? '',
      workOrders: (record.openWorkOrders ?? []).map(wo => wo.number + ' – ' + wo.title),
      blocked: (record.openWorkOrders ?? []).some(wo => wo.fieldLinkStatus === 'Blocked')
    };
  }

  function validateReport(report) {
    const errors = [];
    if (!Object.hasOwn(ISSUE_TYPES, report.issueType)) {
      errors.push({ field: 'issue-type', message: 'Choose an issue type.' });
    }
    if (report.details.length > MAX_DETAILS) {
      errors.push({ field: 'details', message: 'Details must be ' + MAX_DETAILS + ' characters or fewer.' });
    }
    if (report.proceed === 'no' && report.details.trim() === '') {
      errors.push({ field: 'details', message: 'Explain why the visit cannot go ahead.' });
    }
    return errors;
  }

  function buildDispatchMessage(briefing, report, now = new Date()) {
    return JSON.stringify({
      siteCode: briefing.siteCode,
      issueType: report.issueType,
      issueLabel: ISSUE_TYPES[report.issueType],
      details: report.details.trim(),
      canProceed: report.proceed === 'yes',
      reportedOn: now.toISOString()
    }, null, 2);
  }

  // ---------- New in lesson 36: HTTP ----------

  // An error that remembers the HTTP status, so callers can decide what to do.
  class HttpError extends Error {
    constructor(status, message, retryAfterMs) {
      super(message);
      this.name = 'HttpError';
      this.status = status;
      this.retryAfterMs = retryAfterMs;
    }
  }

  // Retry-After is either seconds ("1") or an HTTP date. Returns milliseconds or undefined.
  function parseRetryAfter(value) {
    if (value == null || value === '') return undefined;
    const seconds = Number(value);
    if (Number.isFinite(seconds)) return seconds * 1000;
    const when = Date.parse(value);
    return Number.isNaN(when) ? undefined : Math.max(0, when - Date.now());
  }

  // Transient failures are worth another try; everything else is permanent.
  function isRetryable(error) {
    if (error instanceof HttpError) {
      return error.status === 408 || error.status === 429 || error.status >= 500;
    }
    // fetch rejects with TypeError when the network fails; AbortSignal.timeout gives TimeoutError.
    return error.name === 'TypeError' || error.name === 'TimeoutError';
  }

  // One request: timeout, JSON in and out, non-2xx turned into HttpError.
  // deps lets tests inject a fake fetch instead of calling a real server.
  async function fetchJson(url, init = {}, deps = {}) {
    const fetchFn = deps.fetchFn ?? root.fetch.bind(root);
    const response = await fetchFn(url, {
      ...init,
      headers: { Accept: 'application/json', ...(init.headers ?? {}) },
      signal: AbortSignal.timeout(deps.timeoutMs ?? API.timeoutMs)
    });
    const text = await response.text();
    let body = null;
    if (text) {
      try {
        body = JSON.parse(text);
      } catch {
        throw new HttpError(response.status, 'Response was not JSON (HTTP ' + response.status + ').');
      }
    }
    if (!response.ok) {
      const message = body?.error?.message ?? 'HTTP ' + response.status + '.';
      throw new HttpError(response.status, message, parseRetryAfter(response.headers.get('Retry-After')));
    }
    return body;
  }

  function loadSite(siteCode, deps) {
    return fetchJson(API.base + '/api/sites/' + encodeURIComponent(siteCode), {}, deps);
  }

  // POST with bounded retries. The same Idempotency-Key on every attempt lets
  // the server recognise a repeat and return the first result, not a duplicate.
  async function sendDispatch(messageText, deps = {}) {
    const sleep = deps.sleep ?? (ms => new Promise(resolve => setTimeout(resolve, ms)));
    const key = deps.idempotencyKey ?? root.crypto.randomUUID();
    const maxAttempts = deps.maxAttempts ?? API.maxAttempts;
    for (let attempt = 1; ; attempt++) {
      try {
        // "return await" (not just return) so a rejection is caught below.
        return await fetchJson(API.base + '/api/dispatch-reports', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'Idempotency-Key': key },
          body: messageText
        }, deps);
      } catch (error) {
        if (attempt >= maxAttempts || !isRetryable(error)) throw error;
        const wait = Math.min(error.retryAfterMs ?? 1000 * 2 ** (attempt - 1), 30000);
        deps.onRetry?.(attempt, wait, error);
        await sleep(wait);
      }
    }
  }

  // ---------- Browser-only code ----------
  function readReport(form) {
    const data = new FormData(form);
    return {
      issueType: String(data.get('issueType') ?? ''),
      details: String(data.get('details') ?? ''),
      proceed: String(data.get('proceed') ?? '')
    };
  }

  function setText(id, value) {
    const el = document.getElementById(id);
    if (el) el.textContent = value; // server text is never parsed as HTML
  }

  function renderBriefing(b) {
    setText('site-code', b.siteCode);
    setText('site-contact', b.contact);
    setText('access-hours', b.accessNotes);
    setText('work-order', b.workOrders.join(', ') || 'None');
  }

  function showErrors(form, errors) {
    for (const el of form.querySelectorAll('.error')) el.hidden = true;
    for (const el of form.querySelectorAll('[aria-invalid]')) el.removeAttribute('aria-invalid');
    for (const err of errors) {
      const control = document.getElementById(err.field);
      const box = document.getElementById(err.field + '-error');
      control?.setAttribute('aria-invalid', 'true');
      if (box) { box.textContent = err.message; box.hidden = false; }
    }
    if (errors.length > 0) document.getElementById(errors[0].field)?.focus();
  }

  async function start() {
    const form = document.getElementById('report-form');
    const button = form.querySelector('button[type="submit"]');
    const siteCode = new URLSearchParams(root.location.search).get('site') ?? 'HV-B';

    setText('load-status', 'Loading site briefing…');
    let briefing;
    try {
      briefing = toBriefing(await loadSite(siteCode));
      setText('load-status', '');
    } catch (e) {
      console.error('Cedar site briefing: load failed', e);
      setText('load-status', e.status === 404
        ? 'Site ' + siteCode + ' was not found. Call dispatch.'
        : 'Briefing could not be loaded. Check your connection or call dispatch.');
      button.disabled = true;
      return;
    }
    renderBriefing(briefing);

    let sending = false;
    form.addEventListener('submit', async event => {
      event.preventDefault();
      if (sending) return; // second click while the first request is in flight
      const report = readReport(form);
      const errors = validateReport(report);
      showErrors(form, errors);
      if (errors.length > 0) return;

      sending = true;
      button.setAttribute('aria-disabled', 'true'); // keeps keyboard focus, unlike disabled
      setText('form-status', 'Sending report…');
      try {
        const result = await sendDispatch(buildDispatchMessage(briefing, report), {
          onRetry: (attempt, wait) => setText('form-status',
            'Dispatch did not answer. Retrying in ' + Math.round(wait / 1000) + ' s (attempt ' +
            (attempt + 1) + ' of ' + API.maxAttempts + ')…')
        });
        setText('form-status', 'Report ' + result.reportNumber + ' sent to dispatch.');
        form.reset();
      } catch (e) {
        console.error('Cedar site briefing: send failed', e);
        const reason = e.status >= 400 && e.status < 500 ? e.message : 'dispatch is unavailable.';
        setText('form-status', 'Report not sent: ' + reason + ' Your text is kept. Try again or call dispatch.');
      } finally {
        sending = false;
        button.removeAttribute('aria-disabled');
      }
    });
  }

  const api = {
    ISSUE_TYPES, MAX_DETAILS, API, HttpError,
    toBriefing, validateReport, buildDispatchMessage,
    parseRetryAfter, isRetryable, fetchJson, loadSite, sendDispatch
  };
  root.Cedar = root.Cedar || {};
  root.Cedar.SiteBriefing = api;

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = api; // Node tests
  } else if (typeof document !== 'undefined') {
    start().catch(e => console.error('Cedar site briefing: unexpected error', e));
  }
})(typeof globalThis !== 'undefined' ? globalThis : this);
`,my=String.raw`// tools/mock-dispatch-server.js
// Local stand-in for Cedar's dispatch API. It is NOT FieldLink and NOT Dataverse.
// Serves the site-briefing page and two JSON endpoints on http://localhost:3036.
// Run from the repo root:
//   node tools/mock-dispatch-server.js                  normal
//   node tools/mock-dispatch-server.js --fail-next 2    next 2 POSTs return 503 + Retry-After: 1
//   node tools/mock-dispatch-server.js --delay-ms 15000 every response waits 15 s (timeout test)
'use strict';
const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');

const PORT = 3036;
const PAGE_DIR = path.join(__dirname, '..', 'src', 'webresources', 'prototypes', 'site-briefing');
// Allow-list of static files: never build file paths from the URL (path traversal).
const STATIC = {
  '/': ['site-briefing.html', 'text/html; charset=utf-8'],
  '/site-briefing.css': ['site-briefing.css', 'text/css; charset=utf-8'],
  '/site-briefing.js': ['site-briefing.js', 'text/javascript; charset=utf-8']
};
const ISSUE_TYPES = ['badge', 'locked', 'contact'];

const args = process.argv.slice(2);
const flag = (name, fallback) => (args.includes(name) ? Number(args[args.indexOf(name) + 1]) : fallback);
let failNext = flag('--fail-next', 0);
const delayMs = flag('--delay-ms', 0);

const sample = JSON.parse(fs.readFileSync(path.join(PAGE_DIR, 'site-briefing.sample.json'), 'utf8'));
const sites = new Map([[sample.cedar_sitecode, sample]]);
const reportsByKey = new Map(); // Idempotency-Key -> saved report
let nextNumber = 1;

function sendJson(res, status, body, headers = {}) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}
const problem = (res, status, code, message, headers) => sendJson(res, status, { error: { code, message } }, headers);

function readBody(req, limit = 16 * 1024) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    req.on('data', chunk => {
      size += chunk.length;
      if (size > limit) reject(new Error('Body too large'));
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  console.log(new Date().toISOString(), req.method, url.pathname + url.search);
  if (delayMs) await new Promise(resolve => setTimeout(resolve, delayMs));

  if (req.method === 'GET' && STATIC[url.pathname]) {
    const [file, type] = STATIC[url.pathname];
    res.writeHead(200, { 'Content-Type': type, 'Cache-Control': 'no-store' });
    return fs.createReadStream(path.join(PAGE_DIR, file)).pipe(res);
  }

  const siteMatch = url.pathname.match(/^\/api\/sites\/([^/]+)$/);
  if (siteMatch) {
    if (req.method !== 'GET') return problem(res, 405, 'MethodNotAllowed', 'Use GET.', { Allow: 'GET' });
    const site = sites.get(decodeURIComponent(siteMatch[1]));
    return site ? sendJson(res, 200, site) : problem(res, 404, 'SiteNotFound', 'No site with that code.');
  }

  if (url.pathname === '/api/dispatch-reports') {
    if (req.method !== 'POST') return problem(res, 405, 'MethodNotAllowed', 'Use POST.', { Allow: 'POST' });
    if (failNext > 0) {
      failNext--;
      return problem(res, 503, 'Unavailable', 'Dispatch is busy.', { 'Retry-After': '1' });
    }
    if (!(req.headers['content-type'] ?? '').startsWith('application/json')) {
      return problem(res, 415, 'UnsupportedMediaType', 'Send application/json.');
    }
    let msg;
    try {
      msg = JSON.parse(await readBody(req));
    } catch {
      return problem(res, 400, 'BadJson', 'Body is not valid JSON.');
    }
    if (!sites.has(msg?.siteCode) || !ISSUE_TYPES.includes(msg.issueType) || typeof msg.canProceed !== 'boolean') {
      return problem(res, 400, 'InvalidReport', 'Report needs a known siteCode, an issueType and a boolean canProceed.');
    }
    const key = req.headers['idempotency-key'];
    if (key && reportsByKey.has(key)) return sendJson(res, 200, reportsByKey.get(key)); // repeat: same answer
    // Server fields last, so a client cannot choose its own reportNumber.
    const saved = { ...msg, reportNumber: 'DR-' + String(nextNumber++).padStart(4, '0'), receivedOn: new Date().toISOString() };
    if (key) reportsByKey.set(key, saved);
    return sendJson(res, 201, saved, { Location: '/api/dispatch-reports/' + saved.reportNumber });
  }

  problem(res, 404, 'NotFound', 'No such route.');
});

server.listen(PORT, 'localhost', () => console.log('Mock dispatch API: http://localhost:' + PORT + '/?site=HV-B'));
`,gy=String.raw`// tests/webresources/site-briefing-http.test.js
// Run from the repo root:  node --test "tests/webresources/*.test.js"
// No server needed: each test hands the code a fake fetch that returns real Response objects.
const test = require('node:test');
const assert = require('node:assert/strict');
const SB = require('../../src/webresources/prototypes/site-briefing/site-briefing.js');

const json = (status, body, headers = {}) =>
  new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json', ...headers } });

// Returns the queued responses in order and records every call.
function fakeFetch(...queue) {
  const calls = [];
  const fn = async (url, init) => {
    calls.push({ url, init });
    const next = queue.shift();
    if (next instanceof Error) throw next;
    return next;
  };
  return { fn, calls };
}
const recordSleeps = waits => async ms => { waits.push(ms); };

test('loadSite GETs the encoded site URL and returns parsed JSON', async () => {
  const f = fakeFetch(json(200, { cedar_sitecode: 'HV-B' }));
  const site = await SB.loadSite('HV-B', { fetchFn: f.fn });
  assert.equal(site.cedar_sitecode, 'HV-B');
  assert.equal(f.calls[0].url, '/api/sites/HV-B');
  assert.equal(f.calls[0].init.headers.Accept, 'application/json');
});

test('404 becomes an HttpError with the server message', async () => {
  const f = fakeFetch(json(404, { error: { code: 'SiteNotFound', message: 'No site with that code.' } }));
  await assert.rejects(SB.loadSite('ZZ-9', { fetchFn: f.fn }),
    { name: 'HttpError', status: 404, message: 'No site with that code.' });
});

test('503 is retried once with the same Idempotency-Key after Retry-After', async () => {
  const waits = [];
  const f = fakeFetch(json(503, { error: { message: 'Dispatch is busy.' } }, { 'Retry-After': '1' }),
    json(201, { reportNumber: 'DR-0001' }));
  const result = await SB.sendDispatch('{"siteCode":"HV-B"}',
    { fetchFn: f.fn, sleep: recordSleeps(waits), idempotencyKey: 'k-1' });
  assert.equal(result.reportNumber, 'DR-0001');
  assert.equal(f.calls.length, 2);
  assert.deepEqual(waits, [1000]);
  assert.equal(f.calls[1].init.method, 'POST');
  assert.equal(f.calls[1].init.headers['Idempotency-Key'], 'k-1');
});

test('400 is permanent: exactly one attempt', async () => {
  const f = fakeFetch(json(400, { error: { message: 'Report needs a known siteCode.' } }));
  await assert.rejects(SB.sendDispatch('{}', { fetchFn: f.fn, sleep: async () => {}, idempotencyKey: 'k-2' }),
    { status: 400 });
  assert.equal(f.calls.length, 1);
});

test('network failures stop after 3 attempts with backoff 1 s then 2 s', async () => {
  const waits = [];
  const down = () => new TypeError('Failed to fetch');
  const f = fakeFetch(down(), down(), down());
  await assert.rejects(SB.sendDispatch('{}', { fetchFn: f.fn, sleep: recordSleeps(waits), idempotencyKey: 'k-3' }),
    TypeError);
  assert.equal(f.calls.length, 3);
  assert.deepEqual(waits, [1000, 2000]);
});

test('a request that never answers is aborted by the timeout', async () => {
  const hang = (url, init) => new Promise((resolve, reject) => {
    init.signal.addEventListener('abort', () => reject(init.signal.reason));
  });
  await assert.rejects(SB.loadSite('HV-B', { fetchFn: hang, timeoutMs: 50 }), { name: 'TimeoutError' });
});
